                href="javascript:void(0);" @click="printGeneralOrder(item,item.vendor_data)" class="text-success me-2">
  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-printer" viewBox="0 0 16 16">
    <path d="M2.5 8a.5.5 0 1 0 0-1 .5.5 0 0 0 0 1z"/>
    <path d="M5 1a2 2 0 0 0-2 2v2H2a2 2 0 0 0-2 2v3a2 2 0 0 0 2 2h1v1a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2v-1h1a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-1V3a2 2 0 0 0-2-2H5zM4 3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v2H4V3zm1 5a2 2 0 0 0-2 2v1H2a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v3a1 1 0 0 1-1 1h-1v-1a2 2 0 0 0-2-2H5zm7 2v3a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1z"/>
  </svg>
</a>
<button 
@click="toggleApproval()"
v-if="item.purpose === 'Labour Request' && user_permissions.includes('can_create_labour_voucher')"
class="btn btn-outline-primary">Create Voucher</button>
<router-link :to="`/report/labour-payments/${item.id}`" v-if="item.purpose === 'Labour Request'" class="text-primary">
  view History
</router-link>
          </td>

<td>  
  <a 
                v-if="user_permissions.includes('can_delete_lpo')"
                href="javascript:void(0);" @click="deleteApproval(item)" class="text-danger">
<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-trash" viewBox="0 0 16 16">
  <path d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0z"/>
  <path d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1zM4.118 4 4 4.059V13a1 1 0 0 0 1 1h6a1 1 0 0 0 1-1V4.059L11.882 4zM2.5 3h11V2h-11z"/>
</svg>
                </a>
              </td>
        </tr>
    <tr v-if="item.description ">
      <td colspan="10">
        <b> Brief Description : </b>
        {{ item.description }}
        <span v-if="approval_description"> ( {{ approval_description }} )</span>
      </td>
    </tr>
      <tr v-if="item.remark">
      <td colspan="8"> <b> Remark :  </b> {{ item.remark }}</td>
    </tr>

<tr>
  <td colspan="8" v-if="awaiter.role_id != 2 &&  (item.status?.name === 'Pending Approval' | item.status?.name === 'Expired') ">
    <b> Approval Actions Expires In : </b>
    <span v-if="!expired" class="badge badge-warning">
      {{ hours }}:{{ minutes < 10 ? '0' + minutes : minutes }}:{{ seconds < 10 ? '0' + seconds : seconds }} 
    </span>
  <span v-else class="badge badge-danger">Expired</span>
    <button
      class="btn btn-sm btn-warning ms-2"
      @click="orderRecreation()"
      :disabled="spinner"
      v-if="user_permissions.includes('can_create_lpo') && expired"
    >
      <span v-if="spinner" v-html="loadingSpinner()"></span>
      <span v-else>Recreate Order</span>
    </button>
  </td>
</tr>

      </tbody>
    </table>

    </div>
    </div>
    </div>

    <!-- logs for an order -->


       
<div v-if="item.status?.name === 'approved' && 
           user_permissions.includes('can_complete_transaction') && 
           approvalTransactions.reduce((sum, t) => sum + (t.amount_raw || 0), 0) >= approvalTotalCost"
     class="d-flex justify-content-center mt-2 mb-2">
  <button class="btn btn-primary" type="button" :disabled="loading" 
          @click="complete_transaction = !complete_transaction">
    <span v-if="loading" v-html="loadingSpinner()"></span>
    <span v-else>Paid</span>
  </button>
</div>
 <form v-if="complete_transaction" @submit.prevent="completeTransaction(item.id)">
    <div class="input-group container"  >
  <input type="text" class="form-control"
   placeholder="Enter Any remark "
    v-model="remark">
  <button 
  class="btn btn-primary me-2" type="submit" :disabled="loading">
  <span  v-if="loading" v-html="loadingSpinner()"></span>
  <span v-else>Save</span>
  </button>
</div>
 </form>


        <div class="modal-body">

          <!-- Notes preview -->
<div class="mt-3 mb-3">
  <h5 class="text-center" style="font-size:1rem;">
    Notes
    <span v-if="logs.length" class="badge bg-danger rounded-pill">{{ logs.length }}</span>
  </h5>

  <div v-if="logsLoading" class="text-center py-2">
    <span v-html="waitIndicator()"></span>
  </div>


  <div v-else class="d-flex flex-column gap-2" >
    <template v-for="log in logs" :key="log.id">
      <!-- parent -->
      <div class="d-flex gap-2 align-items-start">
        <div class="avatar-circle avatar-sm flex-shrink-0"
             :style="{ background: avatarBg(log.reporter?.name), color: avatarColor(log.reporter?.name) }">
          {{ log.reporter?.name?.charAt(0)?.toUpperCase() }}
        </div>
        <div class="flex-grow-1">
          <div class="d-flex align-items-center gap-2 flex-wrap">
            <strong style="font-size:13px;">{{ log.reporter?.name }}</strong>
            <small class="text-muted">{{ formatDate(log.created_at) }}</small>
          </div>
          <p style="font-size:13px;margin:0;">{{ log.description }}</p>
        </div>
      </div>

      <!-- replies (level 2), flattened, indented -->
      <div v-for="reply in log.replies || []" :key="reply.id" class="d-flex gap-2 align-items-start ms-4">
        <div class="avatar-circle avatar-xs flex-shrink-0"
             :style="{ background: avatarBg(reply.reporter?.name), color: avatarColor(reply.reporter?.name) }">
          {{ reply.reporter?.name?.charAt(0)?.toUpperCase() }}
        </div>
        <div class="flex-grow-1">
          <div class="d-flex align-items-center gap-2 flex-wrap">
            <strong style="font-size:12px;">{{ reply.reporter?.name }}</strong>
            <small class="text-muted" style="font-size:11px;">{{ formatDate(reply.created_at) }}</small>
          </div>
          <p style="font-size:12px;margin:0;">{{ reply.description }}</p>
        </div>
      </div>

      <!-- nested replies (level 3), flattened further -->
      <div v-for="reply in log.replies || []" :key="'n-' + reply.id">
        <div v-for="nested in reply.replies || []" :key="nested.id" class="d-flex gap-2 align-items-start ms-5">
          <div class="avatar-circle avatar-xs flex-shrink-0"
               :style="{ background: avatarBg(nested.reporter?.name), color: avatarColor(nested.reporter?.name) }">
            {{ nested.reporter?.name?.charAt(0)?.toUpperCase() }}
          </div>
          <div class="flex-grow-1">
            <div class="d-flex align-items-center gap-2 flex-wrap">
              <strong style="font-size:11px;">{{ nested.reporter?.name }}</strong>
              <small class="text-muted" style="font-size:10px;">{{ formatDate(nested.created_at) }}</small>
            </div>
            <p style="font-size:11px;margin:0;">{{ nested.description }}</p>
          </div>
        </div>
      </div>
    </template>
  </div>

  <div class="text-center mt-1">
    <a href="javascript:void(0);" class="btn btn-outline-primary " @click="openNoteModal()">Add Notes</a>
  </div>
</div>
     <!-- logs for an order -->
      
<div class="text-center mb-2">
  <div class="btn-group mb-2">
    <button
      class="btn btn-secondary me-2"
      @click="changeStatus(item.id,3)"
      :disabled="spinner"
      v-if="user_permissions.includes('is_programmer') && item.status?.name === 'paid'"
    >
      Mark Approved
    </button>
    <button
      class="btn btn-success"
      @click="fillReceipt =! fillReceipt"
      :disabled="spinner"
      v-if="user_permissions.includes('can_complete_transaction') &&  item.status?.name === 'paid'"
    >
      Attach Receipt
    </button>
  </div>

  <div v-if="fillReceipt" class="d-flex justify-content-center align-items-end gap-2">
    <input
      class="form-control w-25"
      type="file"
      @change="handleFileUpload"
      accept="application/pdf"
      required
    >
    <input type="date" v-model="receipt_date" class="form-control w-25">

    <button class="btn btn-primary" @click="submitReceipt" :disabled="spinner">
      <span v-if="spinner" v-html="loadingSpinner()"></span>
      <span v-else>Submit</span>
    </button>
  </div>
</div>

        <div class="custom-table table3 table-responsive">
          <table class="table">
            <thead>
              <tr>
                <th v-for="chain in approvalChain" :key="chain.role_id || chain.position || chain.name">
                  {{ chain.name }} <br/>
                </th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td
                  v-for="(role, idx) in approvalChain"
                  :key="role.role_id || role.position || idx"
                  :class="role?.status?.color ? 'text-' + role.status.color : 'text-danger'"
                >
                <span> {{ role?.status?.name ?? 'Unchecked' }}</span><br/>
                <span class="text-dark" v-if="role.approved_at">Checked At  :{{ formatDate(role.approved_at) }} </span>  <br>
                <span class="text-dark" v-if="role.remark">Remark :  {{ role.remark }}</span> 
                </td>
              </tr>
            </tbody>
          </table>
        </div>
